head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil15300";

// TODO Stage2: 세션 키 실환경 확인(회신 11항 · user-info 계약에 없는 키) — session.user.corpUsrTpCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil15300.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_corpUsrTpCd", fn: function(){ return ($c.session.getUserInfo("corpUsrTpCd") !== '19'); } }, { id: "tr_28", fn: function(){ return ($c.session.getUserInfo("corpUsrTpCd") !== '19'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_keyword", fn: function () { return String((dma_pageContext.get("keyword") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_FileDown();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_35_onclick
 * @description img_35 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_35_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil15300.img_35_onclick' }); }
};

/**
 * @method
 * @name grd_lawList_oncellclick
 * @description grd_lawList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_lawList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_lawList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_lawList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["eixstLawBinfile"] === 'Y') { await scwin.fileDown(r["lawNo"]); return; }
        await scwin.viewLawItem(r["lawNo"], r["lawTitle"], r["dtruleLawNo"], r["lawAmendDd"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_lawList.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_ViewLawItem
 * @description View Law Item 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ViewLawItem = async function () {
    const sbmOptions = {
        id: "tx_fn_ViewLawItem",
        method: "post",
        action: "/support/law.do",
        ref: "dma_ViewLawItemReq",
        target: "dlt_lawList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/support/law.do",
        ref: "dma_SearchReq",
        target: "dlt_lawList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_FileDown
 * @description File Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_FileDown = async function () {
    try { return await $c.data.downFile("/support/law.do", "", ($c.util.getComponent("dma_FileDownReq") ? $c.util.getComponent("dma_FileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name viewLawItem
 * @description view Law Item 처리
 * @param {*} _lawNo _lawNo
 * @param {*} _lawTitle _lawTitle
 * @param {*} _dtruleLawNo _dtruleLawNo
 * @param {String} _lawAmendDd _lawAmendDd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.viewLawItem = async function (_lawNo, _lawTitle, _dtruleLawNo, _lawAmendDd) {
    const frm = (document.lawForm || { elements: [] });
    $c.util.getComponent('dma_ViewLawItemReq').set('lawNo', _lawNo);
    $c.util.getComponent('dma_ViewLawItemReq').set('lawTitle', _lawTitle);
    $c.util.getComponent('dma_ViewLawItemReq').set('dtruleLawNo', _dtruleLawNo);
    $c.util.getComponent('dma_ViewLawItemReq').set('lawAmendDd', _lawAmendDd);
    $c.util.getComponent('dma_ViewLawItemReq').set('method', "searchLawItem");
    frm.action = "law.do";
    const nr = await scwin.tx_fn_ViewLawItem();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil15301/jldfil15301.xml", { "lawNo": _lawNo, "lawTitle": _lawTitle, "dtruleLawNo": _dtruleLawNo, "lawAmendDd": _lawAmendDd, "method": "searchLawItem" });
    }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    const frm = (document.lawSearchForm || { elements: [] });
    if (($c.util.getComponent('ipt_keyword').getValue() == null ? '' : String($c.util.getComponent('ipt_keyword').getValue())) === '') {
        await $c.win.alert('검색할 단어를 입력하세요');
        return;
    }
    $c.util.getComponent('dma_ViewLawItemReq').set('method', "searchLawByKeyword");
    frm.action = "law.do";
    const nr = await scwin.tx_fn_Search();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil15303/jldfil15303.xml", { "method": "searchLawByKeyword" });
    }
};

/**
 * @method
 * @name fileDown
 * @description file Down 처리
 * @param {*} _lawNo _lawNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileDown = async function (_lawNo) {
    const frm = (document.fileDownForm || { elements: [] });
    $c.util.getComponent('dma_ViewLawItemReq').set('method', "downLawFile");
    $c.util.getComponent('dma_ViewLawItemReq').set('lawNo', _lawNo);
    frm.action = "law.do";
    await scwin.tx_fn_FileDown();
};
